#include <array>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <vector>
#include <algorithm>
using Rows=std::array<unsigned,8>;
void need(bool ok,const char*s){if(!ok)throw std::runtime_error(s);}
Rows decode(unsigned n,unsigned code){Rows a{};unsigned bit=0;for(unsigned u=0;u<n;u++)for(unsigned v=u+1;v<n;v++,bit++){if(code&(1u<<bit))a[u]|=1u<<v;else a[v]|=1u<<u;}return a;}
unsigned encode(const Rows&a,unsigned n){unsigned code=0,bit=0;for(unsigned u=0;u<n;u++)for(unsigned v=u+1;v<n;v++,bit++)if(a[u]&(1u<<v))code|=1u<<bit;return code;}
Rows transpose(const Rows&a,unsigned n){Rows b{};for(unsigned u=0;u<n;u++)for(unsigned v=0;v<n;v++)if(a[u]&(1u<<v))b[v]|=1u<<u;return b;}
std::array<unsigned,256> ending(const Rows&a,unsigned n){auto in=transpose(a,n);std::array<unsigned,256>d{};for(unsigned mask=1;mask<(1u<<n);mask++){if(!(mask&(mask-1))){d[mask]=mask;continue;}for(unsigned u=0;u<n;u++)if(mask&(1u<<u)){unsigned prior=mask^(1u<<u);if(__builtin_parity(d[prior]&in[u]))d[mask]|=1u<<u;}}return d;}
unsigned subset_even_sum(const Rows&a,unsigned n){auto e=ending(a,n),s=ending(transpose(a,n),n);unsigned t=0,es=0,ss=0;for(unsigned mask=1;mask<(1u<<n);mask++){es^=e[mask];ss^=s[mask];if(!(__builtin_popcount(mask)&1))t^=e[mask]^s[mask];}need(es==s[(1u<<n)-1]&&ss==e[(1u<<n)-1],"complete subset endpoint involution");return t;}
unsigned matrix_t(const Rows&a){bool B[7][7]{},B2[7][7]{},B3[7][7]{};for(unsigned i=0;i<7;i++)for(unsigned j=0;j<7;j++)B[i][j]=(a[i]>>j)&1;for(unsigned i=0;i<7;i++)for(unsigned j=0;j<7;j++)for(unsigned k=0;k<7;k++)B2[i][j]^=B[i][k]&&B[k][j];for(unsigned i=0;i<7;i++)for(unsigned j=0;j<7;j++)for(unsigned k=0;k<7;k++)B3[i][j]^=B2[i][k]&&B[k][j];unsigned t=0;for(unsigned i=0;i<7;i++){bool bit=B3[i][i];for(unsigned j=0;j<7;j++)bit^=B[i][j]^B3[i][j];if(bit)t|=1u<<i;}return t;}
unsigned delete_code(const Rows&a,unsigned deleted){Rows b{};unsigned u2=0;for(unsigned u=0;u<8;u++)if(u!=deleted){unsigned v2=0;for(unsigned v=0;v<8;v++)if(v!=deleted){if(a[u]&(1u<<v))b[u2]|=1u<<v2;v2++;}u2++;}return encode(b,7);}
bool prime(const Rows&a){for(unsigned m=1;m<255;m++)if(__builtin_popcount(m)>=2){bool good=true;for(unsigned u=0;u<8;u++)if(!(m&(1u<<u))){unsigned z=a[u]&m;if(z&&z!=m){good=false;break;}}if(good)return false;}return true;}

unsigned hp_mod8(const std::vector<unsigned>&a){unsigned n=a.size(),N=1u<<n;std::vector<unsigned char>d(size_t(N)*n);for(unsigned u=0;u<n;u++)d[size_t(1u<<u)*n+u]=1;for(unsigned mask=1;mask<N;mask++)for(unsigned u=0;u<n;u++){unsigned z=d[size_t(mask)*n+u];if(!z)continue;unsigned todo=a[u]&~mask;while(todo){unsigned b=todo&-todo;todo-=b;unsigned v=__builtin_ctz(b);auto &r=d[size_t(mask|b)*n+v];r=(r+z)&7;}}unsigned result=0;for(unsigned u=0;u<n;u++)result+=d[size_t(N-1)*n+u];return result&7;}
std::vector<unsigned> physical(const Rows&Q,unsigned n,unsigned c,bool reversed){unsigned N=2*n,x=N,y=N+1;std::vector<unsigned>a(N+2);a[x]=(1u<<y)|((1u<<N)-1);for(unsigned i=0;i<n;i++){a[2*i]|=1u<<(2*i+1);for(unsigned j=0;j<n;j++)if(i!=j&&(((Q[i]>>j)&1)^reversed)){a[2*i]|=3u<<(2*j);a[2*i+1]|=3u<<(2*j);}if(c&(1u<<i)){a[2*i]|=1u<<y;a[2*i+1]|=1u<<y;}else a[y]|=3u<<(2*i);}return a;}
std::array<unsigned,3> physical_controls(){unsigned count=0;for(unsigned n=1;n<=4;n++)for(unsigned code=0;code<(1u<<(n*(n-1)/2));code++){Rows Q=decode(n,code);auto e=ending(Q,n),s=ending(transpose(Q,n),n);unsigned b=e[(1u<<n)-1]^s[(1u<<n)-1];for(unsigned c=0;c<(1u<<n);c++){unsigned x=hp_mod8(physical(Q,n,c,false)),y=hp_mod8(physical(Q,n,c,true));need(((x+8-y)&3)==2u*__builtin_parity(b&c),"independent physical endpoint observer");count+=2;}}Rows Q=decode(8,600653);unsigned x=hp_mod8(physical(Q,8,1,false)),y=hp_mod8(physical(Q,8,1,true));need(x==5&&y==7,"eighteen physical names");return {count,x,y};}
int main(){std::vector<unsigned char>table(1u<<21);std::vector<unsigned>zero;unsigned hist7[128]{};for(unsigned code=0;code<(1u<<21);code++){Rows a=decode(7,code);unsigned direct=subset_even_sum(a,7);need(direct==matrix_t(a),"seven matrix vs complete subset recursion");table[code]=direct;hist7[direct]++;if(!direct)zero.push_back(code);}std::cerr<<"seven table complete: "<<zero.size()<<"\n";std::ofstream seven("independent_seven.bin",std::ios::binary);seven.write((const char*)table.data(),table.size());seven.close();
std::vector<unsigned>bank;std::uint64_t candidates=0;unsigned primes=0;unsigned hist8[256]{};for(unsigned code:zero){Rows base=decode(7,code);for(unsigned incidence=0;incidence<128;incidence++){Rows a=base;for(unsigned u=0;u<7;u++)if(incidence&(1u<<u))a[u]|=128;else a[7]|=1u<<u;candidates++;bool good=true;for(unsigned deleted=0;deleted<7;deleted++)if(table[delete_code(a,deleted)]){good=false;break;}if(!good)continue;auto e=ending(a,8),s=ending(transpose(a,8),8);unsigned bit=e[255]^s[255];hist8[bit]++;need(bit==255,"residual endpoint parity");for(unsigned deleted=0;deleted<8;deleted++){unsigned direct=0;for(unsigned mask=1;mask<256;mask++)if(!(mask&(1u<<deleted))&&!(__builtin_popcount(mask)&1))direct^=e[mask]^s[mask];need(direct==0,"residual direct deletion observer");}bank.push_back(encode(a,8));if(prime(a))primes++;}}
std::sort(bank.begin(),bank.end());need(std::adjacent_find(bank.begin(),bank.end())==bank.end(),"unique extension enumeration");std::ofstream out("independent_eight.bin",std::ios::binary);for(unsigned code:bank)for(unsigned b=0;b<4;b++)out.put((char)((code>>(8*b))&255));out.close();auto physical=physical_controls();std::cout<<"{\"small_physical_queries\":"<<physical[0]<<",\"eighteen_source_mod8\":"<<physical[1]<<",\"eighteen_target_mod8\":"<<physical[2]<<",\"status\":\"PASS\",\"seven_complete_table_size\":"<<table.size()<<",\"seven_zero\":"<<zero.size()<<",\"extension_candidates\":"<<candidates<<",\"eight_residual\":"<<bank.size()<<",\"eight_prime_residual\":"<<primes<<",\"endpoint_xor_255_count\":"<<hist8[255]<<",\"seven_observer_histogram\":[";for(unsigned i=0;i<128;i++){if(i)std::cout<<",";std::cout<<hist7[i];}std::cout<<"],\"first_residual_codes\":[";for(unsigned i=0;i<16;i++){if(i)std::cout<<",";std::cout<<bank[i];}std::cout<<"]}\n";}
